    "यहाँ का वर्कफ़्लो केवल इस योजना पर लागू होता है और संगठन वाले से ऊपर होता है। एक प्रकार का वर्कफ़्लो सभी प्रकारों वाले से ऊपर होता है। हटाई गई स्थिति वाली समस्याएँ उसे बनाए रखती हैं।",
