  "p.access.heading": "पहुँच समीक्षा और आपातकालीन पहुँच",
  "p.access.intro":
    "पहुँच समीक्षा उन पहुँचों की सूची देती है जिन्हें लोगों ने दी गई के रूप में दर्ज किया, पुनः प्रमाणन के लिए। आपातकालीन पहुँच कोई और रास्ता न होने पर एक निजी योजना को सीमित समय के लिए आपके लिए खोलती है; हर उपयोग दर्ज और ऑडिट किया जाता है।",
  "p.access.review_heading": "पहुँच समीक्षा",
  "p.access.review_intro":
    "पहुँच बही में दी गई के रूप में दर्ज और तब से वापस न ली गई पहुँच, सबसे पुरानी पहले, किसने और कब दी, इसके साथ। यह दिखाती है कि लोगों ने क्या दर्ज किया, न कि साइन-इन सेवा क्या लागू करती है: दोनों की तुलना करें। केवल व्यवस्थापकों के लिए; हर बार पढ़ना ऑडिट ट्रेल में दर्ज होता है, इसलिए समीक्षा तभी पढ़ी जाती है जब आप कहें।",
