  "p.meetings.link": "बैठकें, कार्यवृत्त और कार्रवाइयाँ",
  "p.meetings.intro":
    'बैठक की योजना शीर्षक, तिथि और एजेंडा के साथ बनाई जाती है। बाद में उसे एक बार "संपन्न" के रूप में दर्ज किया जाता है, अपने कार्यवृत्त और परिणामों (निर्णय, कार्रवाइयाँ और टिप्पणियाँ) के साथ, या उसे रद्द कर दिया जाता है। संपन्न या रद्द की गई बैठक एक अभिलेख है: संपन्न बैठक का कार्यवृत्त सुधारा नहीं जा सकता और रद्द बैठक को बहाल नहीं किया जा सकता। उपस्थित लोगों को दर्ज नहीं किया जाता।',
  "p.meetings.plan_heading": "बैठक की योजना बनाएँ",
  "p.meetings.plan_says":
    "अधिकतम {title} अक्षरों का शीर्षक और एक तिथि। एजेंडा में अधिकतम {items} मद हो सकते हैं, प्रत्येक अधिकतम {chars} अक्षरों का; कोई मद इस योजना के किसी कार्य, जोखिम, माइलस्टोन या मुद्दे की ओर संकेत कर सकता है।",
