  "p.feed.heading": "कैलेंडर फ़ीड",
  "p.feed.says":
    "एक निजी पता जिसकी सदस्यता कोई कैलेंडर ऐप ले सकता है: आपको सौंपे गए वे खुले कार्य जिनकी नियत तिथि है, उनकी योजनाओं के माइलस्टोन और स्प्रिंट, और आपका नियोजित समय। दूसरा पता फ़ीड रीडर के लिए आपकी सूचनाओं की फ़ीड है। जिसके पास पता है, वह उसमें दिखने वाली बातें पढ़ सकता है, इसलिए इसे अपने तक रखें।",
  "p.feed.rules":
    "पता एक बार, यहीं, दिखाया जाता है और यह पृष्ठ उसे नहीं रखता; यह 365 दिन चलता है। नया बनाने से पहले वाला तुरंत बंद हो जाता है।",
