  "p.watching.says":
    "जब आपकी फ़ॉलो की हुई कोई चीज़ बदलती है, तो आपको बताया जाता है। आप किसी कार्य को तब फ़ॉलो करते हैं जब आप उसे बनाते हैं, उस पर टिप्पणी करते हैं या वह आपको दिया जाता है, जब तक आपने सूचना विकल्पों में इसे बंद न किया हो। किसी और को नहीं बताया जाता कि कौन फ़ॉलो करता है। योजना का नाम दिखता है; बाकी सब उसके प्रकार और संदर्भ की शुरुआत से दिखते हैं।",
