  "p.hammock.heading": "हैमक: दूसरों को समेटने वाले सारांश कार्य",
  "p.hammock.says":
    "हैमक एक सारांश है जिसकी तिथियाँ इस योजना के उन कार्यों से आती हैं जिन्हें वह जोड़ता है, सबसे पहले आरंभ से सबसे बाद के समापन तक। यह निर्भरता नेटवर्क में नहीं है, इसलिए यह कभी किसी कार्य की गुंजाइश या समापन नहीं बदलता। कोई कार्य तभी हैमक बनता है जब उसकी कोई अवधि, काम, बाधा या निर्भरता न हो, और उसका नियोजित आरंभ हटा दिया जाता है; उसे फिर से कार्य बनाने पर उसके सभी लिंक हट जाते हैं। हैमक इस योजना के किसी कार्य या दूसरे हैमक से जुड़ता है, स्वयं से नहीं, दो बार नहीं और चक्र में नहीं।",
  "p.hammock.none": "इस योजना में कोई हैमक नहीं है।",
  "p.hammock.spans": "{range} तक फैला है।",
