  "p.crossplan.heading": "जुड़ी योजनाओं के कार्य",
  "p.crossplan.says":
    "ये उन अन्य योजनाओं के कार्य हैं जिन्हें आप पढ़ सकते हैं और जिनसे इस योजना के कार्य जुड़े हैं, उनकी अपनी योजना के कैलेंडर से निर्धारित। टूटी रेखा वाली पट्टी महत्वपूर्ण पथ से बाहर का कार्य है; ठोस पट्टी और हीरा उस पर का कार्य दिखाते हैं।",
