  "p.ccpm.says":
    "महत्वपूर्ण शृंखला के लिए हर कार्य को एक आक्रामक अनुमान (लगभग बराबर संभावना) और एक सुरक्षित अनुमान चाहिए, 1 से {max} तक पूरे कार्य-दिवसों में, आक्रामक सुरक्षित से ऊपर नहीं। दिखाया गया आँकड़ा दर्ज वाला है, अन्यथा जोखिम सीमा वाला, अन्यथा तैनाती का नियम जो निकाले, और हर एक बताता है कौन सा। मील का पत्थर और बिना अवधि का कार्य अनुमानित नहीं होते। दोनों खाली करने से दर्ज अनुमान हट जाता है।",
